script:
(function () {
  'use strict';
  // Retirement plan for two working spouses, one row per year of your age.
  //   Each spouse saves save% x salary at the end of each year until their own retirement age;
  //   salaries rise by the salary increase. Both accounts earn the pre-retirement return until the
  //   year you have both retired, then the post-retirement return.
  //   From the year both are retired: spending (today's $) x (1 + inflation)^t, less each spouse's
  //   Social Security once they reach their claiming age (today's $, grown with inflation), is
  //   withdrawn at the start of the year, grossed up for tax: W = net / (1 - tax). It comes out of
  //   the two accounts in proportion to their balances.
  //   Savings needed when both retire = present value at the post-retirement return of those
  //   withdrawals through the plan age. Extra saving to close a gap = gap x r / ((1 + r)^N - 1)
  //   a year for the N years until you both retire (gap / N at 0%).
  // Checked in Node (scratch tests): with 0% returns, inflation and raises, $100,000 + $50,000 saved
  //   for 10 years by each spouse at 10% of $50,000 -> $250,000 at household retirement; $40,000
  //   spending less $24,000 Social Security for 20 years needs $320,000; the accounts match
  //   S x 1.06^n + C x (1.06^n - 1.03^n) / 0.03 for one spouse with growing pay; the extra yearly
  //   saving grows to exactly the gap; withdrawals split 2:1 for 2:1 balances.

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return isFinite(x) ? moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x) : '–'; } };
  var one = new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 });

  // p: age1, age2, retire1, retire2, salary1, salary2, save1, save2, bal1, bal2, ss1, ss2 (monthly,
  // today's $), claim1, claim2, spend, planAge, raise, inflation, pre, post, tax (decimals)
  function plan(p) {
    var N = Math.max(p.retire1 - p.age1, p.retire2 - p.age2, 0); // years until both are retired
    var b1 = p.bal1, b2 = p.bal2, rows = [], at1 = null, at2 = null, combined = null;
    var needed = 0, lastsAge = null, first = null;
    if (p.retire1 <= p.age1) at1 = b1;
    if (p.retire2 <= p.age2) at2 = b2;
    for (var t = 0; p.age1 + t < p.planAge; t++) {
      var a1 = p.age1 + t, a2 = p.age2 + t;
      var infl = Math.pow(1 + p.inflation, t), pay = Math.pow(1 + p.raise, t);
      var ss = (a1 >= p.claim1 ? p.ss1 * 12 : 0) * infl + (a2 >= p.claim2 ? p.ss2 * 12 : 0) * infl;
      var c1 = a1 < p.retire1 ? p.salary1 * pay * p.save1 : 0;
      var c2 = a2 < p.retire2 ? p.salary2 * pay * p.save2 : 0;
      var retired = t >= N, rate = retired ? p.post : p.pre, w = 0, w1 = 0, w2 = 0, short = false, spend = 0, net = 0;
      if (retired) {
        if (combined === null) combined = b1 + b2;
        spend = p.spend * infl;
        net = Math.max(0, spend - ss);
        w = net / (1 - p.tax);
        needed += w / Math.pow(1 + p.post, t - N);
        if (first === null) first = { spend: spend, ss: ss, w: w, t: t };
        var total = b1 + b2;
        if (w > total + 1e-9) {
          short = true;
          if (lastsAge === null) lastsAge = a1 + (w > 0 ? total / w : 0);
          w1 = b1; w2 = b2;
        } else if (total > 0) {
          w1 = w * b1 / total; w2 = w - w1;
        }
      }
      b1 = (b1 - w1) * (1 + rate) + c1;
      b2 = (b2 - w2) * (1 + rate) + c2;
      if (a1 + 1 === p.retire1) at1 = b1;
      if (a2 + 1 === p.retire2) at2 = b2;
      rows.push({ a1: a1, a2: a2, contrib: c1 + c2, ss: ss, w: short ? w1 + w2 : w, b1: b1, b2: b2, short: short });
    }
    if (combined === null) combined = b1 + b2;
    var gap = needed - combined;
    var extraYear = 0;
    if (gap > 0 && N > 0) extraYear = p.pre === 0 ? gap / N : gap * p.pre / (Math.pow(1 + p.pre, N) - 1);
    return { N: N, rows: rows, at1: at1, at2: at2, combined: combined, needed: needed, gap: gap, extraYear: extraYear,
             lastsAge: lastsAge, first: first, gapYears: Math.abs((p.retire1 - p.age1) - (p.retire2 - p.age2)) };
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var ids = ['Age1', 'Age2', 'Retire1', 'Retire2', 'Salary1', 'Salary2', 'Save1', 'Save2', 'Bal1', 'Bal2', 'Ss1', 'Ss2',
               'Claim1', 'Claim2', 'Spend', 'PlanAge', 'Raise', 'Inflation', 'Pre', 'Post', 'Tax'];
    var v = {};
    ids.forEach(function (k) { v[k] = num('ts' + k); });
    ['Age1', 'Age2', 'Retire1', 'Retire2', 'Claim1', 'Claim2', 'PlanAge'].forEach(function (k) { v[k] = Math.round(v[k]); });
    var error = document.getElementById('tsError');
    var N = Math.max(v.Retire1 - v.Age1, v.Retire2 - v.Age2, 0);
    var bad = ids.some(function (k) { return isNaN(v[k]); }) ||
              v.Age1 < 18 || v.Age1 > 85 || v.Age2 < 18 || v.Age2 > 85 || v.Retire1 < v.Age1 || v.Retire2 < v.Age2 ||
              v.Retire1 > 85 || v.Retire2 > 85 || v.Claim1 < 62 || v.Claim1 > 70 || v.Claim2 < 62 || v.Claim2 > 70 ||
              v.PlanAge > 110 || v.PlanAge <= v.Age1 + N ||
              [v.Salary1, v.Salary2, v.Bal1, v.Bal2, v.Ss1, v.Ss2, v.Spend].some(function (x) { return x < 0; }) ||
              v.Save1 < 0 || v.Save1 > 100 || v.Save2 < 0 || v.Save2 > 100 || v.Raise < 0 || v.Raise > 20 ||
              v.Inflation < 0 || v.Inflation > 20 || v.Pre < 0 || v.Pre > 30 || v.Post < 0 || v.Post > 30 || v.Tax < 0 || v.Tax > 60;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Check the ages: each retirement age at or above that spouse\'s current age (up to 85), claiming ages 62 to 70, ' +
                          'and a plan age (up to 110) after the year you have both retired. Use non-negative amounts, returns up to 30% and a tax rate up to 60%.';
      return;
    }
    var r = plan({ age1: v.Age1, age2: v.Age2, retire1: v.Retire1, retire2: v.Retire2, salary1: v.Salary1, salary2: v.Salary2,
                   save1: v.Save1 / 100, save2: v.Save2 / 100, bal1: v.Bal1, bal2: v.Bal2, ss1: v.Ss1, ss2: v.Ss2,
                   claim1: v.Claim1, claim2: v.Claim2, spend: v.Spend, planAge: v.PlanAge, raise: v.Raise / 100,
                   inflation: v.Inflation / 100, pre: v.Pre / 100, post: v.Post / 100, tax: v.Tax / 100 });
    var hhAge1 = v.Age1 + r.N, hhAge2 = v.Age2 + r.N;
    set('tsCombinedLabel', 'Savings when you both retire (you ' + hhAge1 + ', spouse ' + hhAge2 + ')');
    set('tsCombined', money.format(r.combined));
    set('tsNeeded', money.format(r.needed));
    set('tsGapLabel', r.gap > 0.5 ? 'Shortfall' : 'Surplus');
    set('tsGap', money.format(Math.abs(r.gap)));
    set('tsAt1Label', 'Your account at ' + v.Retire1);
    set('tsAt1', money.format(r.at1 === null ? v.Bal1 : r.at1));
    set('tsAt2Label', "Spouse's account at " + v.Retire2);
    set('tsAt2', money.format(r.at2 === null ? v.Bal2 : r.at2));
    set('tsGapYears', r.gapYears === 0 ? 'None, you retire together' : r.gapYears + (r.gapYears === 1 ? ' year' : ' years'));
    if (r.first) {
      set('tsSpend0', money.format(r.first.spend));
      set('tsSs0', money.format(Math.min(r.first.ss, r.first.spend)));
      set('tsW0', money.format(r.first.w));
    }
    set('tsLasts', r.lastsAge === null ? 'Beyond your age ' + v.PlanAge : 'Your age ' + Math.floor(r.lastsAge));
    var summary;
    if (r.gap > 0.5) {
      summary = r.N > 0
        ? 'To close the gap, save about ' + money.format(r.extraYear) + ' more a year between you (' + money.format(r.extraYear / 12) +
          ' a month) until you have both retired, or retire later, spend less or delay Social Security.'
        : 'You have both retired, so the gap can only be closed by spending less, working again or adding income.';
    } else {
      summary = 'Your combined savings cover the planned spending through your age ' + v.PlanAge + ', with ' +
                money.format(-r.gap) + ' to spare when you both retire.';
    }
    set('tsSummary', summary);

    var body = document.getElementById('tsSchedule');
    body.textContent = '';
    r.rows.forEach(function (x) {
      var tr = document.createElement('tr');
      [x.a1, x.a2, money.format(x.contrib), money.format(x.ss), money.format(x.w) + (x.short ? ' (runs out)' : ''),
       money.format(x.b1), money.format(x.b2), money.format(x.b1 + x.b2)].forEach(function (val) {
        var td = document.createElement('td'); td.textContent = val; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('tsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
